<?php declare(strict_types=1);require __DIR__.'/includes/config.php';$uid=ir_current_user_id();$q=$pdo->prepare('SELECT file_name,file_path,mime_type FROM wp_ir2_documents WHERE id=? AND user_id=? LIMIT 1');$q->execute([(int)($_GET['id']??0),$uid]);$r=$q->fetch();if(!$r||!$r['file_path']){http_response_code(404);exit('Soubor nenalezen.');}$base=realpath(__DIR__.'/uploads/documents');$path=realpath(__DIR__.'/'.$r['file_path']);if(!$base||!$path||!str_starts_with($path,$base)||!is_file($path)){http_response_code(404);exit('Soubor nenalezen.');}header('Content-Type: '.($r['mime_type']?:'application/octet-stream'));header('Content-Disposition: inline; filename="'.rawurlencode($r['file_name']).'"');header('Content-Length: '.filesize($path));readfile($path);
